// Small MBC3 timer ROM: native joypad, timer, serial, audio, WRAM bank probes.
// No injected multiplayer ABI is required by this core-level fixture.
export function gbFixture(cgb = true, haltRtc = false, pauseBeforeLcd = false, observeWorld = false) {
 const rom = new Uint8Array(32768), labels = new Map(), fixups = [];
 let pc = 0x150;
 const emit = (...bytes) => { rom.set(bytes, pc); pc += bytes.length; };
 const label = name => labels.set(name, pc);
 const jr = (op, name) => { emit(op, 0); fixups.push([pc-1, name]); };
 const store = (addr, value) => emit(0x3e,value,0xea,addr&255,addr>>8);
 emit(0xf3,0x31,0xff,0xdf); // DI, SP
 store(0xff40,0); // LCD off
 // Clear WRAM; independent fresh boot cannot inherit cartridge saves.
 emit(0x21,0,0xc0,0x01,0,0x20); label('clear');
 emit(0xaf,0x22,0x0b,0x78,0xb1); jr(0x20,'clear');
 store(0xc400,0xa5);store(0xff70,1);store(0xd0f0,0x5a);
 if(cgb){store(0xff70,2);store(0xd0f0,0x99);store(0xff70,1);}
 store(0x0000,0x0a);store(0x4000,8); // MBC3 RTC seconds
 // Legacy disk fixtures use the cartridge halt bit, preserving real-time RTC
 // behavior while making their expected restored frames independent of the date.
 if(haltRtc){store(0x4000,12);store(0xa000,0x40);store(0x4000,8);}
 // Square wave and live divider/timer/serial state.
 for(const [a,v] of [[0xff26,0x80],[0xff24,0x77],[0xff25,0x11],[0xff11,0x80],[0xff12,0xf0],[0xff13,0x80],[0xff14,0x87],[0xff06,0x42],[0xff05,0x17],[0xff07,5],[0xff01,0xa5],[0xff02,0x81]])store(a,v);
 // HRAM DMA routine: ROM/stack bus is inaccessible during DMG OAM DMA.
 for(const [i,byte]of [0x3e,0xc1,0xe0,0x46,0x06,0x28,0x05,0x20,0xfd,0xc9].entries())store(0xff80+i,byte);
 // One visible tile and map. Pixels change with input via SCX.
 emit(0x21,0,0x80,0x06,16);label('tile');emit(0x3e,0x55,0x22,0x05);jr(0x20,'tile');
 emit(0x21,0,0x98,0x01,0,4);label('map');emit(0xaf,0x22,0x0b,0x78,0xb1);jr(0x20,'map');
 if(cgb){
  store(0xff4f,1);emit(0x21,0,0x98,0x01,0,4);label('attrs');emit(0xaf,0x22,0x0b,0x78,0xb1);jr(0x20,'attrs');store(0xff4f,0);
  store(0xff68,0x80);for(const byte of [0xff,0x7f,0,0,0x1f,0,0,0x7c])store(0xff69,byte);
 }
 if(pauseBeforeLcd) {
  store(0xc020,0x5a);store(0xff41,8);
  label('paused');emit(0xfa,0x21,0xc0,0xb7);jr(0x28,'paused');
  // Different visible sprite attributes after release exercise restoration of
  // dormant sprite-list entries after the core has visited a later frame.
  for(let i=0;i<4;i++)for(const [j,v]of [16,16+i*24,0,3+i].entries())store(0xfe00+i*4+j,v);
 }
 store(0xff47,0xe4);store(0xff40,pauseBeforeLcd?0x93:0x91);
 label('frame');emit(0xf0,0x44,0xfe,144);jr(0x20,'frame');
 store(0xff00,0x20);emit(0xf0,0,0xea,0x00,0xc0,0xe0,0x43);
 emit(0x21,1,0xc0,0x34);
 if(observeWorld) {
  // World completes, then publishes a 32-bit logical tick before view writes.
  store(0xc006,0x5a);
  for(let i=0;i<4;i++){emit(0x21,0x20+i,0xc0,0x34);if(i<3)jr(0x20,'publishedTick');}
  label('publishedTick');store(0xc024,0xa5);
  store(0xc006,0xa5); // Intentionally different at the native/display boundary.
 }
 emit(0xcd,0x80,0xff); // Call the DMA routine, which waits in HRAM.
 store(0x6000,0);store(0x6000,1);emit(0xfa,0,0xa0,0xea,0x10,0xc0);
 label('end');emit(0xf0,0x44,0xfe,144);jr(0x28,'end');jr(0x18,'frame');
 for(const [at,name]of fixups){const offset=labels.get(name)-(at+1);if(offset < -128 || offset>127)throw Error(name);rom[at]=offset&255;}
 rom.set([0,0xc3,0x50,1],0x100);
 rom.set([0xce,0xed,0x66,0x66,0xcc,0x0d,0,0x0b,3,0x73,0,0x83,0,0x0c,0,0x0d,0,8,0x11,0x1f,0x88,0x89,0,0x0e,0xdc,0xcc,0x6e,0xe6,0xdd,0xdd,0xd9,0x99,0xbb,0xbb,0x67,0x63,0x6e,0x0e,0xec,0xcc,0xdd,0xdc,0x99,0x9f,0xbb,0xb9,0x33,0x3e],0x104);
 rom.set(new TextEncoder().encode('M1 CORE PROBE'),0x134);rom[0x143]=cgb?0x80:0;rom[0x147]=0x10;rom[0x148]=0;rom[0x149]=3;
 let check=0;for(let i=0x134;i<=0x14c;i++)check=(check-rom[i]-1)&255;rom[0x14d]=check;
 let sum=0;for(let i=0;i<rom.length;i++)if(i!==0x14e&&i!==0x14f)sum=(sum+rom[i])&65535;rom[0x14e]=sum>>8;rom[0x14f]=sum&255;
 return rom;
}
